insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_phys_v1'
from (values
('112.45.c.5.A',2,'On a position-versus-time graph, what does the slope of the line represent?','["velocity", "displacement", "acceleration", "force"]'::jsonb,0,'Change in position divided by change in time is velocity.','original'),
('112.45.c.5.A',3,'On a velocity-versus-time graph, what does the slope of the line represent?','["position", "acceleration", "mass", "distance"]'::jsonb,1,'Change in velocity divided by change in time is acceleration.','original'),
('112.45.c.5.A',3,'On a velocity-versus-time graph, what does the area between the line and the time axis represent?','["power", "force", "displacement", "acceleration"]'::jsonb,2,'Velocity times time gives displacement.','original'),
('112.45.c.5.A',2,'What does a horizontal line on a position-versus-time graph show?','["the object is speeding up", "constant acceleration", "constant velocity greater than zero", "the object is at rest"]'::jsonb,3,'The position does not change.','original'),
('112.45.c.5.A',3,'A velocity-versus-time graph shows a straight line sloping upward from the origin. What kind of motion is this?','["constant acceleration from rest", "constant deceleration", "constant velocity", "no motion"]'::jsonb,0,'Velocity increases steadily.','original'),
('112.45.c.5.B',2,'Which of these is a vector quantity?','["mass", "velocity", "distance", "speed"]'::jsonb,1,'A vector has both magnitude and direction.','original'),
('112.45.c.5.B',2,'Which of these is a scalar quantity?','["displacement", "velocity", "speed", "force"]'::jsonb,2,'A scalar has magnitude only.','original'),
('112.45.c.5.B',3,'A 3 N force acts east and a 4 N force acts north on an object. What is the magnitude of the net force?','["7 N", "1 N", "12 N", "5 N"]'::jsonb,3,'√(3² + 4²) = 5.','original'),
('112.45.c.5.B',3,'A 6 N force acts east and a 2 N force acts west on an object. What is the net force?','["4 N east", "4 N west", "8 N east", "12 N east"]'::jsonb,0,'Subtract opposite forces.','original'),
('112.45.c.5.B',3,'A runner completes one lap around a 400 m track and returns to the start. What is the runner''s displacement?','["800 m", "0 m", "200 m", "400 m"]'::jsonb,1,'Displacement compares the final position with the starting position.','original'),
('112.45.c.5.C',2,'A cyclist travels 100 m in 20 s at a constant speed. What is the speed?','["80 m/s", "0.2 m/s", "5 m/s", "2000 m/s"]'::jsonb,2,'Speed = distance ÷ time.','original'),
('112.45.c.5.C',3,'A car goes from 0 to 20 m/s in 5 s. What is its acceleration?','["15 m/s²", "100 m/s²", "0.25 m/s²", "4 m/s²"]'::jsonb,3,'a = Δv ÷ t.','original'),
('112.45.c.5.C',3,'A car starts from rest and accelerates at 2 m/s² for 5 s. How far does it travel?','["25 m", "10 m", "50 m", "5 m"]'::jsonb,0,'d = ½at² = ½(2)(25).','original'),
('112.45.c.5.C',3,'Ignoring air resistance, about how fast is an object falling after 3 s of free fall from rest? (g ≈ 9.8 m/s²)','["3.3 m/s", "29.4 m/s", "88 m/s", "9.8 m/s"]'::jsonb,1,'v = gt.','original'),
('112.45.c.5.C',3,'A person walks 3 m east and then 3 m west. What is the total distance traveled?','["0 m", "3 m", "6 m", "9 m"]'::jsonb,2,'Distance adds up all of the path length.','original'),
('112.45.c.5.D',3,'In uniform circular motion, in which direction does the acceleration point?','["it is zero", "away from the center", "along the direction of motion", "toward the center of the circle"]'::jsonb,3,'Centripetal acceleration points inward.','original'),
('112.45.c.5.D',3,'An object moves at 4 m/s on a circle of radius 2 m. What is its centripetal acceleration?','["8 m/s²", "16 m/s²", "2 m/s²", "0.5 m/s²"]'::jsonb,0,'a = v² ÷ r = 16 ÷ 2.','original'),
('112.45.c.5.D',3,'Ignoring air resistance, what happens to the horizontal velocity of a horizontally launched projectile?','["it reverses", "it stays constant", "it increases", "it decreases"]'::jsonb,1,'No horizontal force acts on it.','original'),
('112.45.c.5.D',4,'One ball is dropped and another is launched horizontally from the same height at the same moment. Ignoring air resistance, which lands first?','["it depends on mass", "the dropped ball", "they land at the same time", "the launched ball"]'::jsonb,2,'Vertical motion is identical for both.','original'),
('112.45.c.5.D',4,'An object moves in a circle at constant speed. Why is it accelerating?','["no force acts on it", "its speed keeps changing", "its mass keeps changing", "its direction of velocity keeps changing"]'::jsonb,3,'Velocity is a vector, and its direction changes.','original'),
('112.45.c.5.E',2,'According to Newton''s first law, what happens to a moving object with no net force on it?','["it continues moving at constant velocity", "it speeds up", "it slows down", "it stops immediately"]'::jsonb,0,'Objects keep their motion unless acted on by a net force.','original'),
('112.45.c.5.E',2,'What is inertia?','["the force of gravity", "the tendency of an object to resist changes in its motion", "the energy of an object", "the speed of an object"]'::jsonb,1,'More mass means more inertia.','original'),
('112.45.c.5.E',3,'Which quantity is a measure of an object''s inertia?','["acceleration", "weight only", "mass", "velocity"]'::jsonb,2,'Greater mass resists change in motion more.','original'),
('112.45.c.5.E',3,'A passenger lurches forward when a car brakes suddenly. Which idea explains this?','["gravity pulls forward", "friction increases", "action and reaction", "inertia"]'::jsonb,3,'The body tends to keep moving.','original'),
('112.45.c.5.E',3,'What is true about the net force on an object in equilibrium?','["it is zero", "it equals the weight", "it is greater than zero", "it points downward"]'::jsonb,0,'Forces balance.','original'),
('112.45.c.5.F',3,'What is the net force on a 10 kg object accelerating at 3 m/s²?','["3.3 N", "30 N", "13 N", "7 N"]'::jsonb,1,'F = ma.','original'),
('112.45.c.5.F',3,'What is the weight of a 5 kg object near Earth''s surface? (g ≈ 9.8 m/s²)','["0.5 N", "4.9 N", "49 N", "5 N"]'::jsonb,2,'W = mg.','original'),
('112.45.c.5.F',3,'A 20 N force pushes a box right and a 5 N friction force pushes left. What is the net force?','["100 N right", "15 N left", "25 N right", "15 N right"]'::jsonb,3,'Subtract the opposing force.','original'),
('112.45.c.5.F',2,'Which force acts perpendicular to a surface and supports an object resting on it?','["the normal force", "tension", "centripetal force", "friction"]'::jsonb,0,'It pushes away from the surface.','original'),
('112.45.c.5.F',3,'Which force keeps a car moving in a circle on a flat curve?','["a force pointing away from the center", "friction between the tires and the road, acting as a centripetal force", "gravity pulling outward", "the engine force forward"]'::jsonb,1,'A center-directed force is needed.','original'),
('112.45.c.5.G',2,'According to Newton''s third law, forces between two objects are what?','["different in size", "equal and in the same direction", "equal in size and opposite in direction", "always zero"]'::jsonb,2,'For every action there is an equal and opposite reaction.','original'),
('112.45.c.5.G',3,'A rocket moves forward when it pushes exhaust gas backward. Which law explains this?','["Newton''s first law", "Newton''s second law", "the law of conservation of charge", "Newton''s third law"]'::jsonb,3,'The gas pushes the rocket in return.','original'),
('112.45.c.5.G',3,'When you push on a wall, what does the wall do?','["pushes back with an equal force", "absorbs the force", "does nothing", "pushes back with a smaller force"]'::jsonb,0,'Action-reaction forces are equal.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Science' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
