from (values
('112.45.c.5.G',4,'Why don''t the action and reaction forces cancel each other out?','["they are different sizes", "they act on different objects", "they act in the same direction", "they happen at different times"]'::jsonb,1,'A net force requires forces on the same object.','original'),
('112.45.c.5.H',3,'If the distance between two masses doubles, what happens to the gravitational force between them?','["it is halved", "it quadruples", "it becomes one-fourth", "it doubles"]'::jsonb,2,'Gravity follows an inverse square law.','original'),
('112.45.c.5.H',3,'If one of two masses doubles, what happens to the gravitational force between them?','["it stays the same", "it quadruples", "it is halved", "it doubles"]'::jsonb,3,'Force is proportional to each mass.','original'),
('112.45.c.5.H',3,'What is the approximate value of the universal gravitational constant G?','["6.67 × 10⁻¹¹ N·m²/kg²", "3.0 × 10⁸ m/s", "9.8 m/s²", "6.67 × 10¹¹ N·m²/kg²"]'::jsonb,0,'A very small number, so gravity is weak between everyday objects.','original'),
('112.45.c.5.H',4,'If both masses and the distance between them are all doubled, what happens to the gravitational force?','["it becomes one-fourth", "it stays the same", "it doubles", "it quadruples"]'::jsonb,1,'Masses give a factor of 4 and distance gives a factor of 1/4.','original'),
('112.45.c.6.A',3,'If the distance between two charges doubles, what happens to the electric force between them?','["it is halved", "it doubles", "it becomes one-fourth", "it quadruples"]'::jsonb,2,'The electric force also follows an inverse square law.','original'),
('112.45.c.6.A',2,'How do two objects with opposite charges interact?','["they have no force between them", "they repel each other", "they merge", "they attract each other"]'::jsonb,3,'Opposite charges attract.','original'),
('112.45.c.6.A',3,'If one charge triples while the other charge and distance stay the same, what happens to the electric force?','["it triples", "it becomes one-third", "it is nine times as large", "it stays the same"]'::jsonb,0,'Force is proportional to each charge.','original'),
('112.45.c.6.A',4,'The Coulomb constant k is about 9 × 10⁹ N·m²/C². What is this number in standard form?','["90,000,000,000", "9,000,000,000", "900,000,000", "9,000,000"]'::jsonb,1,'10⁹ means 9 followed by 9 zeros.','original'),
('112.45.c.6.B',3,'What does an electric generator do?','["converts light into sound", "stores charge permanently", "converts mechanical energy into electrical energy using a magnetic field", "converts electrical energy into heat only"]'::jsonb,2,'A coil spins in a magnetic field.','original'),
('112.45.c.6.B',3,'What does an electric motor do?','["makes magnets weaker", "converts motion into electricity", "produces static charge", "converts electrical energy into mechanical energy using magnetic forces"]'::jsonb,3,'Current in a magnetic field experiences a force.','original'),
('112.45.c.6.B',2,'Why does the needle of a compass point north?','["it aligns with Earth''s magnetic field", "it is pulled by gravity", "it is attracted by the Moon", "it is charged"]'::jsonb,0,'Earth acts like a giant magnet.','original'),
('112.45.c.6.B',3,'Which everyday device uses electromagnets to lift scrap metal?','["a flashlight", "a junkyard crane magnet", "a thermometer", "a mirror"]'::jsonb,1,'Current through a coil creates a magnetic field that can be switched on and off.','original'),
('112.45.c.6.C',3,'A balloon rubbed on hair becomes negative and the hair becomes positive. What does this show?','["protons moved to the balloon", "charge was destroyed", "electrons moved from the hair to the balloon", "charge was created"]'::jsonb,2,'Electrons are transferred and total charge stays the same.','original'),
('112.45.c.6.C',3,'Charging by conduction requires what?','["a magnet", "a battery only", "no contact at all", "direct contact between a charged object and a neutral object"]'::jsonb,3,'Charge flows during contact.','original'),
('112.45.c.6.C',4,'Charging by induction results in a final charge on the neutral object that is what?','["opposite to the charged object that was brought near", "the same as the charged object", "always neutral", "random"]'::jsonb,0,'Charges rearrange and then the object is grounded.','original'),
('112.45.c.6.C',3,'What does the law of conservation of charge say?','["charge is only positive", "the total charge in an isolated system stays the same", "charge disappears over time", "charge can be created from nothing"]'::jsonb,1,'Charge is transferred, not created or destroyed.','original'),
('112.45.c.6.D',3,'In a series circuit, how many paths are there for current?','["two", "as many as there are bulbs", "one", "none"]'::jsonb,2,'All components are connected in a single loop.','original'),
('112.45.c.6.D',3,'In a series circuit, what happens if one bulb burns out?','["only that bulb goes out", "nothing changes", "the other bulbs get brighter", "all bulbs go out"]'::jsonb,3,'The circuit is broken.','original'),
('112.45.c.6.D',3,'In a parallel circuit, what is the same across each branch?','["the voltage", "the current", "the power", "the resistance"]'::jsonb,0,'Each branch connects to the same two points.','original'),
('112.45.c.6.D',3,'Two resistors of 2 Ω and 3 Ω are connected in series. What is the total resistance?','["1 Ω", "5 Ω", "6 Ω", "1.2 Ω"]'::jsonb,1,'Resistances add in series.','original'),
('112.45.c.6.D',4,'Two identical 6 Ω resistors are connected in parallel. What is the total resistance?','["6 Ω", "12 Ω", "3 Ω", "36 Ω"]'::jsonb,2,'Equal resistors in parallel divide the resistance by the number of resistors.','original'),
('112.45.c.6.D',3,'Why are household outlets wired in parallel?','["so that all devices turn off together", "so that voltage is split", "so that no current flows", "each device gets the full voltage and works independently"]'::jsonb,3,'One device can be off while others stay on.','original'),
('112.45.c.6.E',3,'A 12 V battery is connected to a 4 Ω resistor. What is the current?','["3 A", "0.33 A", "48 A", "8 A"]'::jsonb,0,'I = V ÷ R.','original'),
('112.45.c.6.E',3,'A device carries 2 A at 10 V. How much power does it use?','["12 W", "20 W", "0.2 W", "5 W"]'::jsonb,1,'P = IV.','original'),
('112.45.c.6.E',3,'A circuit has 9 V and 3 A. What is the resistance?','["0.33 Ω", "12 Ω", "3 Ω", "27 Ω"]'::jsonb,2,'R = V ÷ I.','original'),
('112.45.c.6.E',3,'What is the unit of electric power?','["ampere", "volt", "ohm", "watt"]'::jsonb,3,'One watt is one joule per second.','original'),
('112.45.c.6.E',4,'If the voltage across a fixed resistor doubles, what happens to the current?','["it doubles", "it is halved", "it stays the same", "it quadruples"]'::jsonb,0,'Current is proportional to voltage.','original'),
('112.45.c.7.A',3,'How much work does a 10 N force do pushing a box 5 m in the direction of the force?','["15 J", "50 J", "2 J", "0.5 J"]'::jsonb,1,'W = Fd.','original'),
('112.45.c.7.A',3,'A person holds a heavy box without moving it. How much work is done on the box?','["work equal to its mass", "work equal to its weight", "none, because there is no displacement", "a lot, because the force is large"]'::jsonb,2,'Work needs displacement in the direction of the force.','original'),
('112.45.c.7.A',3,'A machine does 100 J of work in 5 s. What is its power?','["0.05 W", "500 W", "95 W", "20 W"]'::jsonb,3,'P = W ÷ t.','original'),
('112.45.c.7.A',4,'A waiter carries a tray at constant speed across a flat room. Does the waiter''s upward force on the tray do work?','["No, because the force is perpendicular to the motion", "Yes, because the tray moves", "Yes, because there is a force", "Yes, because the tray has weight"]'::jsonb,0,'Work depends on the component of force along the motion.','original'),
('112.45.c.7.B',3,'What is the kinetic energy of a 2 kg object moving at 3 m/s?','["18 J", "9 J", "6 J", "3 J"]'::jsonb,1,'KE = ½mv².','original')
) as v(code, diff, prompt, choices, ans, expl, src)
