join public.teks_documents d on d.id = i.document_id and d.subject = 'Science' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_phys_v1'
from (values
('112.45.c.8.D',4,'An ambulance siren sounds higher in pitch as it approaches. This is called what?','["polarization", "total internal reflection", "refraction", "the Doppler effect"]'::jsonb,3,'The waves are compressed in front of the moving source.','original'),
('112.45.c.8.E',3,'Radio telescopes detect what kind of waves from space?','["radio waves", "ultraviolet waves", "X-rays", "sound waves"]'::jsonb,0,'Large dishes collect radio signals.','original'),
('112.45.c.8.E',3,'Which electromagnetic waves are used to cook food in a microwave oven?','["gamma rays", "microwaves", "ultraviolet rays", "X-rays"]'::jsonb,1,'They make water molecules vibrate.','original'),
('112.45.c.8.E',3,'Which electromagnetic waves are used for medical imaging of bones?','["microwaves", "radio waves", "X-rays", "infrared waves"]'::jsonb,2,'They pass through soft tissue more easily than bone.','original'),
('112.45.c.8.E',3,'Night-vision devices detect which type of electromagnetic radiation?','["radio", "gamma", "ultraviolet", "infrared"]'::jsonb,3,'Warm objects emit infrared.','original'),
('112.45.c.8.F',3,'Why does each element have a unique emission spectrum?','["its electrons have a unique set of energy levels", "it has a different mass", "its protons have different colors", "its neutrons emit light"]'::jsonb,0,'Each atom emits only certain wavelengths.','original'),
('112.45.c.8.F',3,'How is a photon emitted by an atom?','["the nucleus splits", "an electron drops to a lower energy level", "a proton leaves the nucleus", "an electron moves to a higher energy level"]'::jsonb,1,'The energy difference is released as light.','original'),
('112.45.c.8.F',4,'How do astronomers learn what elements a star contains?','["by measuring its temperature only", "by touching it", "by analyzing the spectrum of its light", "by weighing it"]'::jsonb,2,'The spectral lines match known elements.','original'),
('112.45.c.8.G',3,'What kind of image does a plane mirror form?','["a real, enlarged image", "a real, inverted image", "no image", "a virtual image, the same size as the object, behind the mirror"]'::jsonb,3,'The image appears as far behind the mirror as the object is in front.','original'),
('112.45.c.8.G',3,'What does the law of reflection state?','["the angle of incidence equals the angle of reflection", "light bends toward the normal", "the angle of incidence is twice the reflection angle", "light speeds up"]'::jsonb,0,'Both angles are measured from the normal.','original'),
('112.45.c.8.G',3,'Light entering glass from air slows down. How does it bend?','["away from the normal", "toward the normal", "it does not bend", "it reflects completely"]'::jsonb,1,'Light bends toward the normal in a slower medium.','original'),
('112.45.c.8.G',4,'What does a converging (convex) lens do to parallel light rays?','["absorbs them", "reflects them", "bends them toward a focal point", "spreads them apart"]'::jsonb,2,'It focuses light.','original'),
('112.45.c.8.G',4,'Why does light stay inside an optical fiber?','["polarization", "diffraction at the walls", "absorption by the walls", "total internal reflection at the walls"]'::jsonb,3,'Light hits the boundary at angles greater than the critical angle.','original'),
('112.45.c.9.A',4,'In the photoelectric effect, electrons are ejected from a metal only if the light has what?','["frequency above a threshold value", "intensity above a threshold value", "any color", "wavelength above a threshold value"]'::jsonb,0,'Photon energy must exceed the work function.','original'),
('112.45.c.9.A',4,'Increasing the brightness of light below the threshold frequency has what effect on the photoelectric effect?','["more electrons are ejected", "no electrons are ejected", "faster electrons are ejected", "electrons are ejected only at first"]'::jsonb,1,'Each photon must carry enough energy on its own.','original'),
('112.45.c.9.A',3,'Which model of light explains the photoelectric effect?','["light as sound", "light as a continuous wave only", "light as photons with energy E = hf", "light as heat"]'::jsonb,2,'Einstein proposed light comes in quanta.','original'),
('112.45.c.9.A',4,'Emission spectra show only specific wavelengths. What does this indicate about atomic energy levels?','["they are random", "they are continuous", "they do not exist", "they are quantized"]'::jsonb,3,'Only certain energy differences are possible.','original'),
('112.45.c.9.B',4,'What does the polarization of light show about its nature?','["light is a transverse wave", "light has no direction", "light is a longitudinal wave", "light is a sound wave"]'::jsonb,0,'Only transverse waves can be polarized.','original'),
('112.45.c.9.B',4,'Two polarizing filters are crossed at 90°. How much light passes through both?','["a quarter of it", "almost none", "all of it", "half of it"]'::jsonb,1,'cos²(90°) = 0.','original'),
('112.45.c.9.B',4,'Light of intensity 100 passes through a polarizer whose axis is 30° from the light''s polarization. By Malus''s law, about what intensity passes?','["87", "50", "75", "25"]'::jsonb,2,'100 × cos²30° = 100 × 0.75.','original'),
('112.45.c.9.B',3,'Why do polarized sunglasses reduce glare?','["they block all light", "they change the color of light", "they increase frequency", "they block horizontally polarized reflected light"]'::jsonb,3,'Reflected glare is mostly polarized.','original'),
('112.45.c.9.B',3,'How do 3-D movie glasses create separate images for each eye?','["each lens polarizes light in a different direction", "each lens makes images bigger", "each lens is a mirror", "each lens changes the frequency"]'::jsonb,0,'Two differently polarized images are shown on the screen.','original'),
('112.45.c.9.C',3,'What is wave-particle duality?','["light is only a particle", "matter and light show both wave and particle behavior", "waves cannot have energy", "matter is only a wave"]'::jsonb,1,'The behavior depends on the experiment.','original'),
('112.45.c.9.C',4,'Electrons sent through two slits form an interference pattern. What does this show?','["electrons are not particles at all", "electrons are heavier than protons", "electrons can behave like waves", "electrons are charged only"]'::jsonb,2,'A wave-like pattern builds up from individual electrons.','original'),
('112.45.c.9.C',4,'What does superposition of quantum states mean?','["a system can only be in one state", "a system is always at rest", "a system cannot be measured", "a system can exist in a combination of states until measured"]'::jsonb,3,'Measurement gives one outcome.','original'),
('112.45.c.9.C',3,'What is a photon?','["a quantum (packet) of light energy", "a negative ion", "a type of sound", "a unit of mass"]'::jsonb,0,'Its energy depends on frequency.','original'),
('112.45.c.9.D',4,'The Heisenberg uncertainty principle says that you cannot do what?','["measure energy at all", "know the exact position and momentum of a particle at the same time", "use light", "see any particle"]'::jsonb,1,'There is a limit to how precisely both can be known.','original'),
('112.45.c.9.D',4,'What do quantum computers use in place of ordinary bits?','["ordinary bits only", "analog gears", "qubits that can be in superposition", "transistors that cannot switch"]'::jsonb,2,'A qubit can be in a combination of 0 and 1.','original'),
('112.45.c.9.D',3,'Which everyday devices rely on quantum mechanics?','["plain mirrors", "wooden chairs", "bicycles", "LEDs, lasers and transistors"]'::jsonb,3,'Their operation depends on quantized energy levels.','original'),
('112.45.c.9.D',3,'What principle allows an electron microscope to see very small objects?','["electrons have wave properties with very short wavelengths", "light has long wavelengths", "electrons are heavy", "electrons are positive"]'::jsonb,0,'Shorter wavelength gives better resolution.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Science' and d.language = 'en'
on conflict (fingerprint) do nothing;
